(() => {
  const worlds=[
    {name:'The original web',subtitle:'THE RAIMI TRILOGY',hero:'Peter Parker · Tobey Maguire',image:'media/spider1.jpg',era:'tobey',color:'#f25a67',description:'New York rooftops, a neighborhood hero, and the responsibility that comes with power. Explore the original three-film story, from the Green Goblin to Doctor Octopus and beyond.'},
    {name:'The amazing city',subtitle:'THE AMAZING SPIDER-MAN',hero:'Peter Parker · Andrew Garfield',image:'media/amazing1.jpg',era:'andrew',color:'#5caaff',description:'A new Peter Parker, a different New York. Follow Gwen Stacy, Oscorp’s secrets, and a hero finding his own way through a two-film story.'},
    {name:'The neighborhood',subtitle:'THE MCU SPIDER-MAN FILMS',hero:'Peter Parker · Tom Holland',image:'media/homecoming.jpg',era:'tom',color:'#efbc60',description:'From high-school life to reality-crossing adventures. Follow Peter through Homecoming, Far From Home, No Way Home, and Brand New Day.'},
    {name:'Beyond the frame',subtitle:'THE ANIMATED SPIDER-VERSE',hero:'Miles Morales · Animated',image:'media/into.jpg',era:'miles',color:'#f16f8b',description:'Comic-book energy becomes a world of its own. Meet Miles Morales, Gwen Stacy, and Spider-heroes from other realities in the animated Spider-Verse films.'}
  ];
  const $=s=>document.querySelector(s),viewport=$('#verse-viewport'),rig=$('#verse-rig');if(!viewport)return;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let active=0,angle=0,pitch=-7,targetAngle=null,auto=false,drag=null,lastTime=0,visiblePage=location.hash.slice(1)||'home',portalOpen=false,portalTimer=null;
  $('#verse-tabs').innerHTML=worlds.map((w,i)=>`<button data-verse="${i}" aria-pressed="${i===0}" style="--world-color:${w.color}"><span></span>${['Tobey’s world','Andrew’s world','Tom’s world','Miles’ world'][i]}</button>`).join('');
  $('#verse-nodes').innerHTML=worlds.map((w,i)=>`<div class="verse-node" style="--node-angle:${i*90}deg;--world-color:${w.color}"><div class="verse-facing"><button class="verse-card" data-verse-card="${i}" aria-label="Explore ${w.hero}" aria-pressed="${i===0}"><div class="portal-halo" aria-hidden="true"></div><div class="verse-card-image"><img src="${w.image}" alt="" loading="lazy" width="1200" height="1800"><span class="verse-card-symbol" aria-hidden="true">✳</span></div><div class="verse-card-caption"><span>WORLD 0${i+1}</span><strong>${['TOBEY','ANDREW','TOM','MILES'][i]}</strong></div></button></div></div>`).join('');
  function resize(){const w=viewport.clientWidth||600;rig.style.setProperty('--orbit-radius',Math.min(225,w*.29)+'px');rig.style.setProperty('--card-width',Math.min(175,Math.max(100,w*.265))+'px')}
  if(typeof ResizeObserver!=='undefined')new ResizeObserver(resize).observe(viewport);resize();
  function closePortal(){portalOpen=false;viewport.classList.remove('portal-open');$('#verse-status').textContent='WORLD IN FOCUS';$('#verse-open').innerHTML='Open portal <span>✳</span>';$('#verse-open').setAttribute('aria-pressed','false');$('#portal-web').replaceChildren();if(portalTimer)clearTimeout(portalTimer)}
  function update(){const w=worlds[active];$('#verse-subtitle').textContent=w.subtitle;$('#verse-name').textContent=w.name;$('#verse-description').textContent=w.description;$('#verse-hero').textContent=w.hero;$('.verse-detail').style.setProperty('--world-color',w.color);document.querySelectorAll('[data-verse]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.verse===active)));document.querySelectorAll('[data-verse-card]').forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===active));b.closest('.verse-node').classList.toggle('selected',i===active)})}
  function setAuto(value){auto=value;$('#verse-auto').setAttribute('aria-pressed',String(auto));$('#verse-auto').textContent=auto?'Pause orbit':'Auto orbit'}
  function select(i){active=(i+worlds.length)%worlds.length;const wanted=-active*90;targetAngle=angle+(((wanted-angle)%360+540)%360-180);if(reduced){angle=targetAngle;targetAngle=null;render()}setAuto(false);closePortal();update()}
  document.querySelectorAll('[data-verse]').forEach(b=>b.onclick=()=>select(+b.dataset.verse));document.querySelectorAll('[data-verse-card]').forEach(b=>b.onclick=()=>{if(dragged)return;select(+b.dataset.verseCard)});
  $('#verse-prev').onclick=()=>select(active-1);$('#verse-next').onclick=()=>select(active+1);$('#verse-auto').onclick=()=>{targetAngle=null;setAuto(!auto)};$('#verse-reset').onclick=()=>{angle=0;pitch=-7;targetAngle=null;select(0);render()};
  $('#verse-movies').onclick=()=>{showPage('guide',true);$('#search').value='';$('#series').value=worlds[active].era;renderMovies()};
  $('#verse-open').onclick=()=>{if(portalOpen){closePortal();return}setAuto(false);const w=worlds[active];portalOpen=true;viewport.classList.add('portal-open');$('#verse-status').textContent='PORTAL OPEN · '+w.hero.split(' · ')[0].toUpperCase();$('#verse-open').innerHTML='Close portal <span>×</span>';$('#verse-open').setAttribute('aria-pressed','true');$('#portal-web').innerHTML='<g class="portal-thread"><path d="M 300 440 Q 120 280 300 140 M 300 440 Q 480 280 300 140 M 300 440 L 300 140"/><path d="M 300 140 L 240 100 L 210 150 L 230 210 L 300 240 L 370 210 L 390 150 L 360 100 Z"/><path d="M 300 140 L 210 150 M 300 140 L 230 210 M 300 140 L 300 240 M 300 140 L 370 210 M 300 140 L 390 150 M 300 140 L 360 100 M 300 140 L 240 100"/></g>';portalTimer=setTimeout(()=>$('#portal-web').replaceChildren(),2500);window.dispatchEvent(new CustomEvent('webverse-enter',{detail:{...w,index:active}}))};
  let dragged=false;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('#verse-controls'))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};dragged=false;setAuto(false);targetAngle=null});viewport.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const moved=Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY);if(moved>6){dragged=true;if(!viewport.hasPointerCapture?.(e.pointerId))viewport.setPointerCapture?.(e.pointerId)}angle+=(e.clientX-drag.x)*.4;pitch=Math.max(-24,Math.min(18,pitch-(e.clientY-drag.y)*.13));drag.x=e.clientX;drag.y=e.clientY;render()});function end(e){if(drag&&drag.id===e.pointerId){drag=null;setTimeout(()=>dragged=false,0)}}viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);viewport.addEventListener('lostpointercapture',()=>drag=null);
  viewport.tabIndex=0;viewport.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();select(active+(e.key==='ArrowRight'?1:-1))}});
  function render(){rig.style.setProperty('--orbit-angle',angle+'deg');rig.style.setProperty('--counter-angle',-angle+'deg');rig.style.setProperty('--orbit-pitch',pitch+'deg')}
  function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-lastTime)/1000,.05)||0;lastTime=now;if(visiblePage!=='home'||document.hidden)return;if(targetAngle!==null){const delta=targetAngle-angle;angle+=delta*Math.min(1,dt*8);if(Math.abs(delta)<.05){angle=targetAngle;targetAngle=null}}else if(auto&&!drag){angle-=dt*9}render()}
  window.addEventListener('webverse-world-open',e=>{if(!e.detail)closePortal()});window.addEventListener('assemble-page',e=>{visiblePage=e.detail;lastTime=performance.now()});update();render();requestAnimationFrame(frame);
})();
